import React from 'react'
import './Footer.css'

import {Container, Row, Col, ListGroup, ListGroupItem} from "reactstrap"
import {Link} from 'react-router-dom'
import logo from "../../assets/images/logo.png"

const Footer = () => {

  const quick_links = [
  {
    path: '/home',
    display: 'Home'
  },
  {
    path: 'about',
    display: 'Về chúng tôi'
  },
  {
    path: '/tour',
    display: 'Tour'
  },
]
const quick_links2 = [
  {
    path: '/gallery',
    display: 'Bộ sưu tập'
  },
  {
    path: 'Login',
    display: 'Đăng nhập'
  },
  {
    path: '/register',
    display: 'Đăng ký'
  },
]
  return (
    <footer className='footer'>
      <Container>
        <Row>
          <Col lg = "3">
            <div className="logo">
              
            </div>
          </Col>
        </Row>
      </Container>
    </footer>
  )
}

export default Footer
